<?php
namespace App\Domain\Capabilities; use App\Domain\PublicChrome\PublicAssetPath; use App\Models\{Capability,CapabilityCategory}; use Illuminate\Support\Facades\Cache; use Throwable; final class CapabilityIndexViewData { public function get(?string $category,int $page):array{try{return Cache::remember('public.capabilities.index.v1.'.CapabilityCache::indexVersion().'.'.($category?:'all').'.'.now()->format('YmdHi').'.'.$page,now()->addMinutes(10),fn()=>$this->load($category,$page));}catch(Throwable){return $this->load($category,$page);}} private function load(?string $category,int $page):array{$categoryModel=$category?CapabilityCategory::where('slug',$category)->where('is_active',true)->first():null;if($category&&!$categoryModel)return ['invalid'=>true,'items'=>[],'categories'=>[],'pagination'=>[]];$p=Capability::publiclyVisible()->with('category')->when($categoryModel,fn($q)=>$q->whereBelongsTo($categoryModel))->orderByDesc('is_featured')->orderBy('display_order')->paginate(12,['*'],'page',$page);return ['invalid'=>false,'categories'=>CapabilityCategory::where('is_active',true)->orderBy('display_order')->limit(50)->get()->map(fn($c)=>['name'=>$c->name,'slug'=>$c->slug])->all(),'items'=>$p->getCollection()->map(fn($item)=>['title'=>$item->title,'description'=>$item->short_description,'featured'=>(bool)$item->is_featured,'image'=>PublicAssetPath::isSafe($item->featured_image_path)?$item->featured_image_path:null,'image_alt'=>$item->featured_image_alt,'category'=>$item->category?->name,'url'=>route('capabilities.show',$item->slug)])->all(),'pagination'=>['current'=>$p->currentPage(),'last'=>$p->lastPage(),'previous'=>$p->previousPageUrl(),'next'=>$p->nextPageUrl(),'total'=>$p->total()]];} }
